      "title": "文献所录碑铭",
      "name": "文献所录碑铭",
      "type": "碑刻",
      "materialType": "碑刻",
      "sourceTitle": "《两晋金石录（2025.06.21更新）》",
      "sourceDocument": "两晋金石录（2025.06.21更新）.docx",
